import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../domain/entities/complaint_entities.dart';import '../../domain/repositories/complaint_repository.dart';import '../datasources/complaint_datasource.dart';import '../stores/complaint_runtime_store.dart';
final complaintRepositoryProvider=Provider<ComplaintRepository>((ref)=>ComplaintRepositoryImpl(ComplaintLocalDataSource(ComplaintRuntimeStore.instance)));
class ComplaintRepositoryImpl implements ComplaintRepository{final ComplaintDataSource _source;const ComplaintRepositoryImpl(this._source);@override Future<Complaint> submit(ComplaintDraft d)async=>(await _source.submit(d)).toEntity();@override Future<Complaint?> get({required String requestId,required String customerId,required String providerId})async=>(await _source.get(requestId:requestId,customerId:customerId,providerId:providerId))?.toEntity(); @override Future<List<ComplaintAttachment>> pickImages({required int remaining})=>_source.pickImages(remaining:remaining);}
